    [DataRow("1234567890", "(123) 456-7890")]
    [DataRow("5551234567", "(555) 123-4567")]
    public void FormatPhoneNumber_ValidDigits_ReturnsFormattedNumber(string digits, string expected)
    {
        var result = _formatter.FormatPhoneNumber(digits);

        Assert.AreEqual(expected, result);
    }

    [TestMethod]
    [DataRow("1234567890", "(")]
    [DataRow("5551234567", "(555)")]
    public void FormatPhoneNumber_ValidDigits_StartsWithAreaCodeInParens(string digits, string expectedPrefix)
    {
        var result = _formatter.FormatPhoneNumber(digits);

        Assert.StartsWith(expectedPrefix, result);
    }

    [TestMethod]
    [DataRow("1234567890", "7890")]
    [DataRow("5551234567", "4567")]
    public void FormatPhoneNumber_ValidDigits_EndsWithLastFourDigits(string digits, string expectedSuffix)
    {
        var result = _formatter.FormatPhoneNumber(digits);

        Assert.EndsWith(expectedSuffix, result);
    }

    [TestMethod]
    public void FormatPhoneNumber_ContainsDashSeparator()
    {
        var result = _formatter.FormatPhoneNumber("1234567890");

        Assert.Contains("-", result);
    }

    [TestMethod]
    [DataRow("1234567890", @"\(\d{3}\) \d{3}-\d{4}")]
    public void FormatPhoneNumber_MatchesExpectedPattern(string digits, string pattern)
    {
        var result = _formatter.FormatPhoneNumber(digits);

        Assert.MatchesRegex(pattern, result);
    }

    [TestMethod]
    public void FormatPhoneNumber_NullInput_ThrowsArgumentNullException()
    {
        var ex = Assert.ThrowsExactly<ArgumentNullException>(() => _formatter.FormatPhoneNumber(null!));

        Assert.AreEqual("digits", ex.ParamName);
    }

    [TestMethod]
    [DataRow("123")]
    [DataRow("12345678901")]
    [DataRow("")]
    public void FormatPhoneNumber_InvalidLength_ThrowsArgumentException(string digits)
    {
        Assert.ThrowsExactly<ArgumentException>(() => _formatter.FormatPhoneNumber(digits));
    }

    [TestMethod]
    [DataRow("Alice", "Mr.", "Dear Mr. Alice,")]
    [DataRow("Bob", "Dr.", "Dear Dr. Bob,")]
    public void BuildGreeting_WithNameAndTitle_ReturnsFullGreeting(string name, string title, string expected)
    {
        var result = _formatter.BuildGreeting(name, title);

        Assert.AreEqual(expected, result);
    }

    [TestMethod]
    public void BuildGreeting_DefaultTitle_StartsWithDearMr()
    {
        var result = _formatter.BuildGreeting("Smith");

        Assert.StartsWith("Dear Mr.", result);
    }

    [TestMethod]
    [DataRow("Alice", ",")]
    [DataRow("Bob", ",")]
    public void BuildGreeting_AlwaysEndsWithComma(string name, string expectedSuffix)
    {
        var result = _formatter.BuildGreeting(name);

        Assert.EndsWith(expectedSuffix, result);
    }

    [TestMethod]
    public void BuildGreeting_ContainsName()
    {
        var result = _formatter.BuildGreeting("Johnson", "Mrs.");

        Assert.Contains("Johnson", result);
    }

    [TestMethod]
    public void BuildGreeting_NullName_ThrowsArgumentException()
    {
        Assert.ThrowsExactly<ArgumentNullException>(() => _formatter.BuildGreeting(null!));
    }

    [TestMethod]
    [DataRow("")]
    [DataRow("   ")]
    public void BuildGreeting_WhitespaceName_ThrowsArgumentException(string name)
    {
        Assert.ThrowsExactly<ArgumentException>(() => _formatter.BuildGreeting(name));
    }

    [TestMethod]
    [DataRow("Hello World", "hello-world")]
    [DataRow("  My Blog Post  ", "my-blog-post")]
    [DataRow("C# is Great!", "c-is-great")]
    [DataRow("multiple   spaces", "multiple-spaces")]
    public void GenerateSlug_ValidTitle_ReturnsExpectedSlug(string title, string expected)
    {
        var result = _formatter.GenerateSlug(title);

        Assert.AreEqual(expected, result);
    }

    [TestMethod]
    public void GenerateSlug_Result_MatchesSlugPattern()
    {
        var result = _formatter.GenerateSlug("Some Title! @#$");

        Assert.MatchesRegex(@"^[a-z0-9]+(-[a-z0-9]+)*$", result);
    }

    [TestMethod]
    public void GenerateSlug_NullTitle_ThrowsArgumentNullException()
    {
        Assert.ThrowsExactly<ArgumentNullException>(() => _formatter.GenerateSlug(null!));
    }

    [TestMethod]
    [DataRow("")]
    [DataRow("   ")]
    public void GenerateSlug_WhitespaceTitle_ThrowsArgumentException(string title)
    {
        Assert.ThrowsExactly<ArgumentException>(() => _formatter.GenerateSlug(title));
    }

    [TestMethod]
    [DataRow(19.99, "$", "$19.99")]
    [DataRow(0.5, "€", "€0.50")]
    [DataRow(1000, "£", "£1000.00")]
    public void FormatCurrency_ReturnsFormattedAmount(double amount, string symbol, string expected)
    {
        var result = _formatter.FormatCurrency((decimal)amount, symbol);

        Assert.AreEqual(expected, result);
    }

    [TestMethod]
    [DataRow(42.50, "$", "$")]
    [DataRow(10.00, "€", "€")]
    public void FormatCurrency_StartsWithSymbol(double amount, string symbol, string expectedPrefix)
    {
        var result = _formatter.FormatCurrency((decimal)amount, symbol);

        Assert.StartsWith(expectedPrefix, result);
    }

    [TestMethod]
    public void FormatCurrency_DefaultSymbol_StartsWithDollarSign()
    {
        var result = _formatter.FormatCurrency(25.00m);

        Assert.StartsWith("$", result);
    }

    [TestMethod]
    [DataRow(10.99, ".99")]
    [DataRow(5.00, ".00")]
    public void FormatCurrency_EndsWithDecimalPortion(double amount, string expectedSuffix)
    {
        var result = _formatter.FormatCurrency((decimal)amount);

        Assert.EndsWith(expectedSuffix, result);
    }

    [TestMethod]
    public void FormatCurrency_AlwaysHasTwoDecimalPlaces()
    {
        var result = _formatter.FormatCurrency(7m);

        Assert.MatchesRegex(@"\d+\.\d{2}$", result);
    }
}

